  "{0} has already been stripped of its valuables. Damaged harbor defenses remain under military guard until they recover.": "{0} はすでに略奪され、価値ある品は残っていません。港の損傷した防備は、修復されるまで軍の警備下にあります。",
  "{0} has been plundered. Your raiders carry off {1} doubloons, but the city remains under its former flag.": "{0} が略奪されました。襲撃者たちは {1} 個のダブロンを持ち去りましたが、都市は以前の旗のままです。",
