  "{0} has fallen. The commissioners negotiated terms with its rulers, and the princes and envoys made peace. The treasury will pay the reward for {1}'s extraordinary commission.": "{0} は陥落しました。全権委員が統治者と条件を交渉し、諸侯と使節が和平を結びました。財務局は{1}の特別任務の報奨金を支払います。",
  "{0} has forbidden {1} from {2}": "{0}は{1}に{2}を禁じました。",
  "{0} has lost its last port, but loyal servants have not abandoned the flag. This expedition can keep our cause alive overseas until fortune turns.": "{0} は最後の港を失いましたが、忠実な家臣たちは旗を捨てませんでした。この遠征により、運命が変わるまで海外で私たちの大義を存続させることができます。",
