  "{0} has received the answer. The treasury pays you {1} doubloons.": "{0} は返答を受け取りました。財務局からあなたに{1}ダブロンが支払われます。",
  "{0} has received the chancery's sealed receipt. The treasury pays {1} db for your passage.": "{0} は封印された政府の領収書を受け取りました。財務省は、通行料として {1} DB を支払います。",
  "{0} has received the receiving court's acknowledgment. The treasury will pay {1} doubloons.": "{0} は受理裁判所の承認を受け取りました。財務省は {1} ダブロンを支払います。",
  "{0} has sealed instructions for the election of a {1}. Carry me to {2} and back home for a payment of {3} doubloons. My prince alone chooses; your duty is to carry us safely.": "{0} には、{1} の選出に関する指示が封印されています。 {2} まで送ってもらい、{3} ダブロンの支払いで家に戻ります。私の王子様だけが選択します。あなたの義務は私たちを安全に運ぶことです。",
  "{0} has surrendered. You seize {1} doubloons from its treasury.{2}{3}": "{0} は降伏しました。国庫から{1}ダブロンを押収しました。{2}{3}",
