  "Demand surrender": "降伏要求",
  "Demand surrender anyway": "とにかく降伏を要求する",
  "DEMO": "デモ",
  "Denali rises from low country with scarcely any warning, an immense wall of snow above rivers and dark forest. Clouds crossed its middle while the summit remained in another weather.": "デナリは低地から突如そびえ、川と暗い森の上に巨大な雪壁を築いています。雲が山腹を横切る一方、頂上は別の天候に包まれていました。",
  "denied a Papal commission": "教皇の依頼を拒否した",
  "Denmark-Norway": "デンマーク - ノルウェー",
  "DEPRIVATION": "剥奪",
  "Deputy Governor": "副知事",
  "Deputy Governor {0}": "副知事 {0}",
  "Destroy pirate haven": "海賊の隠れ家を破壊する",
  "Destroyed": "破壊された",
  "Dexterity, memory, and a complete absence of respect for property. I shall record the first two qualities in the formal account.": "手先の器用さ、記憶力、そして財産への敬意の完全な欠如。最初の 2 つの性質を正式な説明に記録します。",
  "Dhaulagiri appeared as an enormous white wall above the river gorge, its glaciers broken into blue steps. The valley made the summit seem almost impossibly near and impossibly high at once.": "ダウラギリは、渓谷の上に巨大な白い壁のように見え、その氷河は青い階段に分かれていました。谷のせいで、頂上がありえないほど近くにあると同時に、ありえないほど高く見えた。",
  "Dhow": "ダウ船",
  "Diet of Worms dialogue": "ヴォルムス帝国議会の会話",
  "DIG OUT": "氷を砕く",
  "Diplomatic customs": "外交慣習",
  "Diplomatic mission": "外交任務",
  "DIPLOMATIC MISSION ADVANCES": "外交任務の前進",
  "Discover El Dorado.": "エルドラドを発見してください。",
  "Discovered {0}": "{0} を発見しました",
  "Disease and hunger have emptied the fort. Relations with Powhatan have worsened as the English demand food the drought has made scarce for everyone.": "病気と飢えで砦は空になった。英国人が干ばつで不足してしまった食糧を要求しているため、ポーハタン族との関係は悪化している。",
  "Dismiss": "解雇",
  "DISMISS": "解雇",
  "Dismiss {0}": "{0}を解雇",
  "Dismiss {0} crew before taking this vessel.": "この船を引き継ぐ前に乗組員を{0}人解雇してください。",
  "Distinct ship types sailed": "さまざまな種類の船が出航しました",
  "Diu kept its walls free of Portugal. Your estate was less fortunate with me.": "ディウはポルトガル勢を城壁の内に入れませんでした。だが、あなたの屋敷は私に奪われてしまいましたね。",
  "DIVIDEND PAID": "配当金支払い",
  "DIVIDENDS PAID": "配当金支払額",
  "Do you think the fish smell us coming, or have they gone mercifully numb?": "魚は私たちの気配を嗅ぎつけているのかな。それとも、ありがたいことに感覚が鈍ってしまったのかな。",
  "Dock at the remote village of Hawaii.": "ハワイの人里離れた村に停泊します。",
  "Dock: {0}": "{0}に入港",
  "Does that strange bear earn its passage, or does it merely eat the provisions?": "あの妙なクマは船の食い扶持に見合う働きをするのかな。それとも食料を食べるだけ？",
  "Does your small black-and-white officer always smell so strongly of fish?": "その白黒の小さな士官は、いつもこんなに魚臭いのですか？",
