  "durable, visible trade goods for the upriver market": "上流市場向けの丈夫で目に見える貿易品",
  "Dust from the caravan road settles on the landing, where merchants weigh news from inland against news from the sea.": "キャラバンの道から舞い上がった砂埃が船着き場に積もる。商人たちは内陸と海から届いた知らせを比べている。",
  "Dutch negotiated trade post": "オランダの交渉交易所",
  "Dutch settler colony": "オランダ人入植者の植民地",
  "DUTY {0}%": "関税{0}%",
  "Each day brings us nearer to {0} and the road to Mecca. I have waited years for the Hajj; I pray our passage remains safe.": "日ごとに{0}とメッカへ続く道に近づいている。何年も待ち望んだハッジだ。旅路の安全を祈ろう。",
  "Eagle": "イーグル",
  "EARLIER ACCOUNTS": "過去の会計",
  "EARLIER DIVIDENDS": "前期の配当",
