  "Engaged by a {0}": "{0}に攻撃された",
  "England": "イングランド",
  "ENGLAND BREAKS WITH ROME": "イングランド、ローマと決別",
  "English": "イングランド人",
  "English Bermuda colony": "イギリス領バミューダ植民地",
