  "Knotted records pass from the landing to waiting runners as coastal cargo begins its journey inland.": "沿岸貨物が内陸への旅を始めると、結び目のあるレコードが着陸地から待機しているランナーに渡されます。",
  "Knows when to press a bargain and when to let a factor save face.": "いつ取引を迫るべきか、いつ港商の面目を保つべきかを知っている。",
  "Knows where fish gather and how to bring them aboard.": "魚が集まる場所と魚を乗せる方法を知っています。",
  "Kobaya": "Kobaya",
  "Kongo": "コンゴ",
  "Korean": "韓国人",
  "Kosciuszko is no lonely spire. It is the highest rise in a broad, windswept country of rounded ridges, pale grass, and winter snow.": "コジオスコは孤立した尖峰ではありません。丸い尾根と淡い草地、冬の雪が広がる風の強い高原で、最も高く盛り上がった場所です。",
  "Kreeee!": "クリーエィ！",
  "Krrrk!": "クルクル！",
  "Krrrk?": "クルクル？",
  "Krrrk.": "クルルク。",
  "Kyoto must hear what was promised at {0}, and what was conspicuously left unsaid.": "京都は{0}で約束されたこと、そして明らかに言われなかったことを聞かなければなりません。",
  "Kyoto's offices reward a quick change of allegiance. Creditors prefer consistency.": "京都の事務所は、忠誠心をすぐに変えると報いる。債権者は一貫性を好みます。",
