  "Laced iron scales spread a blow across the body without the weight of solid plate.": "編み込まれた鉄の鱗は、固体板のような重みを持たずに体全体に衝撃を広げます。",
  "Lake sturgeon": "レイクチョウザメ",
  "Lake Titicaca": "チチカカ湖",
  "Lake Titicaca lies beneath snow-covered Andes, yet its water spreads like a sea among the high plains. Reed boats and floating reed islands move upon its deep blue surface.": "チチカカ湖は雪に覆われたアンデス山脈の下にありますが、その水は高原の間に海のように広がります。葦のボートや浮かぶ葦の島々がその深い青色の表面を移動します。",
  "Lake trout": "レイクトラウト",
