  "Lawful wartime attack": "合法的な戦時攻撃",
  "Lead Hull Sheathing": "鉛の船体外装",
  "Lead plates can turn aside a glancing shot or protect the hull during a grounding.": "鉛板はかすめる砲弾をそらし、座礁時には船体を守ることがある。",
  "League": "リーグ",
  "Lean stores, maximum trade room": "無駄のない店舗、最大限の取引スペース",
  "Leave": "休暇を取る",
  "Leave {0} at the nearest safe shore": "{0}を一番近い安全な海岸に残す",
  "leave for our merchants to enter Ming ports under lawful seal, customs, and the emperor's peace": "合法的な封印、慣習、そして皇帝の平和の下で商人たちが明の港に入港できるよう出発します。",
  "Leave it ashore": "岸に置いておく",
  "Leave port": "出港",
