  "PAPAL ARMS BAN AGAINST {0}: OBSERVED BY {1}": "{0}への教皇の武器禁輸：遵守国 {1}",
  "PAPAL ARMS BAN AGAINST {0}: OBSERVED BY {1} POLITIES": "{0}に対する教皇の武器禁輸：{1}の国が遵守",
  "Papal Commendation": "教皇表彰",
  "PAPAL GRAIN ALMS UNDERWAY FOR {0}": "{0} に対する教皇による穀物援助が進行中",
  "PAPAL LEGATION EXPIRED - ROME ACTS WITHOUT US": "教皇公使館の期限が切れました - ローマは私たちなしで行動します",
  "PAPAL LEGATION REVOKED": "教皇公使館が取り消される",
