  "Prince-Bishopric of Utrecht": "ユトレヒト司教王子",
  "princes and envoys made peace. The treasury will pay the reward for": "王子と使者は和平を結びました。国庫が報酬を支払うことになる",
  "Princes change in Targoviste. A sealed debt survives every throne.": "トゥルゴヴィシュテでは王子たちが変わります。封印された借金はどの王座にも残ります。",
