  "Remarkable. Leave the penguin in my care and I shall pay you {payment} doubloons. I have fish, ink, and several questions he may decline to answer.": "すごいですね。ペンギンを私に預けてください。{支払い} ダブロンをお支払いします。私には魚、インク、そして彼が答えられないかもしれないいくつかの質問があります。",
  "Remember me when that bright sail rises over the horizon.": "あの明るい帆が地平線に昇るとき、私を思い出してください。",
