  "sails, vestments, bedding, and a hospital": "帆、祭服、寝具、病院",
  "Saint Croix taught us to fear cold more than distance. Bring": "セントクロイ島は私たちに、距離よりも寒さを恐れるように教えてくれました。持参する",
  "Sale prices +{0}": "セール価格 +{0}",
  "SALES": "販売",
  "Salisbury Plain": "ソールズベリー平原",
  "Salmon": "サーモン",
  "Salvador needs grain while officials, soldiers, builders, and clergy continue to arrive.": "役人、兵士、建築業者、聖職者が続々と到着する中、サルバドールは穀物を必要としている。",
  "Salvador now stands as Brazil's fortified capital, with government on the heights and Atlantic commerce below.": "サルバドールは現在、ブラジルの要塞首都として立っており、高台に政府があり、下に大西洋の商業が存在します。",
  "Sampan": "Sampan",
  "sangat singer": "サンガット歌手",
  "Sangat's gift": "サンガットの贈り物",
  "Sanriku whaling grounds": "三陸捕鯨場",
  "Santa Maria": "サンタマリア",
  "Santiago de Leon de Caracas now holds the valley, and the Indian name Caracas has already outlasted the one in the charter.": "現在この渓谷はサンティアゴ・デ・レオン・デ・カラカスが所有しており、インドの名前であるカラカスはすでに憲章にある名前よりも長く使われています。",
  "Sao Paulo de Luanda has become Portugal's fortified Angolan port. Its Atlantic wealth comes from inland war and the slave trade.": "サンパウロ デ ルアンダはポルトガルのアンゴラの要塞港となっています。大西洋の富は内陸戦争と奴隷貿易から来ています。",
  "Sao Sebastiao cannot secure Guanabara without more powder.": "サン・セバスティアンは、さらなる火薬がなければグアナバラを確保することはできない。",
  "Sao Sebastiao has secured Guanabara Bay for Portugal. Around the old redoubt, Rio de Janeiro is becoming a true port.": "サン・セバスティアンはポルトガルのグアナバラ湾を確保した。古い要塞の周囲で、リオデジャネイロは真の港になりつつあります。",
  "Sapa Inca": "サパ・インカ",
  "Sapa Inca {0}": "サパ インカ {0}",
  "Sardine": "イワシ",
  "Satsuma's divided branches agree on at least one thing: your bond is valid.": "薩摩の分断された支部は、少なくとも 1 つの点で同意します。それは、あなたの絆が有効であるということです。",
