  "SEA": "海",
  "SEA ICE PARTED THE HARPOON LINE": "海氷が銛線を分断",
  "Sea Venture survivors built Deliverance and Patience from Bermuda cedar before reaching Jamestown. Their account now inspires a town at St. George's.": "シー ベンチャーの生存者は、ジェームスタウンに到着する前に、バミューダ杉でデリバランスとペイシェンスを構築しました。彼らの記述は現在、セントジョージズの町にインスピレーションを与えています。",
  "Sea-road renewal": "海道路リニューアル",
  "Seal those spice bales. Half the crew is sneezing us off course.": "スパイスの俵を封印してください。乗組員の半分がコースから外れてくしゃみをしています。",
