  "Sell cinnamon, nutmeg, pepper, cloves, and ginger in one voyage.": "シナモン、ナツメグ、コショウ、クローブ、ジンジャーを 1 回の航海で販売します。",
  "Sell five different kinds of goods in one voyage.": "1 回の航海で 5 種類の商品を販売する。",
  "Sell it anyway": "それでも売る",
  "Sell the entrusted tea": "お預かりしたお茶を販売します",
  "Sell the sealed {0}": "封印された{0}を売却する",
