  "SEND IT ASHORE": "陸上に送る",
  "Sep": "9月",
  "Serbian": "セルビア人",
  "Service to the Pope": "教皇への奉仕",
  "Set {0} ashore {1} db": "{0} を {1} DB に設定します。",
  "Set a course for {0}.": "{0} のコースを設定します。",
  "Set a double watch whenever we carry precious metal. Greed travels farther than any pirate.": "貴金属を運ぶ時は見張りを倍にしよう。欲深さはどんな海賊より遠くまで届く。",
  "Set a heading for {0}": "{0} の見出しを設定します",
  "Set crew, guns, and stores. Extra hands improve field work and gun loading. Smaller stores dump excess provisions without refund.": "乗組員、銃、店舗を設定します。追加のハンドにより、現場作業と銃の装填が向上します。小規模店舗は過剰な食料品を返金せずに廃棄する。",
  "SET CREW, GUNS, FOOD, AND WATER": "乗組員、銃、食料、水の準備",
  "Set heading: {0} ({1}; harbor barred)": "針路を設定：{0}（{1}、入港禁止）",
  "Set heading: {0} ({1})": "見出しの設定: {0} ({1})",
  "Set passenger ashore {0} db": "乗客を上陸させます {0} DB",
  "Set Sail": "出航",
  "Sets and trims canvas before the wind can shift.": "風が吹く前にキャンバスをセットしてトリミングします。",
  "Settlement founded.": "入植地を建設。",
  "settlers whose first crops have failed": "最初の作物が失敗した入植者",
  "Seven Seas": "セブンシーズ",
  "Several commissions are waiting. Choose one charge; your chart will mark the way.": "いくつかのコミッションが待っています。 1 つの料金を選択してください。あなたのチャートが道を示すでしょう。",
  "Several people look up as you enter.": "入ると、何人かが顔を上げる。",
  "Shabout": "シャブート",
  "Shah": "シャー",
  "Shah {0}": "シャー {0}",
  "Shall I strike every market trade made during this visit from the ledger and restore your coin, cargo, and the merchant's stock?": "今回の訪問中に行われたすべての市場取引を台帳から調べて、あなたのコイン、貨物、商人の在庫を復元しましょうか?",
  "shape stocks and ramrods for the first workshop batch": "最初のワークショップバッチ用にストックとラムロッドを成形する",
  "Sharif": "シャリフ",
  "Sharif {0}": "シャリフ {0}",
  "Sharifate of Mecca": "メッカのシャリファテ",
  "Shasta rises by itself above the forests, a broad volcanic cone with a smaller shoulder beside it. Snowfields catch the light long after the lower country has gone dark.": "シャスタは森の上に単独でそびえ立ち、その横に小さな肩を持つ広い火山円錐形です。下地が暗くなってからずっと後、雪原は光を捉えます。",
  "Shawmut has good water but little ready shelter for a fleet of families. Bring": "ショームットには良質な水がありますが、家族連れが泊まれる避難場所はほとんどありません。持参する",
  "Shawmut's spring solves the water crisis that plagued Charlestown. We will establish Boston on this narrow peninsula in the country of the Massachusett.": "ショームットの泉は、チャールズタウンを悩ませていた水危機を解決します。私たちはマサチューセッツ州のこの狭い半島にボストンを設立します。",
  "Shawnee": "ショーニー",
  "Shimazu": "島津",
  "Shimazu House": "島津家住宅",
  "Shinto-Buddhist": "神仏習合",
