  "SHIPBUILDING COSTS": "造船コスト",
  "Ships": "船",
  "Ships and mills cannot run on promises. Complete the harbor stores with": "船や工場は約束どおりに動くことはできません。港の店舗を完了する",
  "Ships or port attacked": "船舶または港が攻撃された",
  "Ships, carts, and warehouse crews crowd the waterfront; every arrival changes some merchant's plans.": "船、荷車、倉庫作業員がウォーターフロントに群がります。到着するたびに一部の商人の計画が変更されます。",
  "Shipshape": "船の形",
  "Shipwright": "船大工",
