  "shipyard measurements": "造船所の測定",
  "Shipyard report: a new {0} is for sale in {1}.": "造船所レポート: 新しい {0} が {1} で販売されています。",
  "Shipyard report: a pre-owned {0} is for sale in {1}.": "造船所報告：{1}で中古の{0}が売りに出ています。",
